module.exports = vm

function vm (code, done, options = {}) {
  if (typeof code !== 'function') throw new Error('code must be a function')
  const mode = options.mode || 'controlled'
  if (mode !== 'controlled' && mode !== 'sandboxed') throw new Error('mode must be controlled or sandboxed')
  const document = options.document || globalThis.document
  const state = { port: null, closed: false }
  const src = URL.createObjectURL(new Blob([get_child_source()], { type: 'text/html' }))
  const vmview = document.createElement('div')
  const shadow = vmview.attachShadow({ mode: 'closed' })
  const iframe = document.createElement('iframe')
  iframe.setAttribute('sandbox', 'allow-scripts')
  iframe.setAttribute('title', options.title || 'Sandboxed runtime')
  iframe.src = src
  iframe.onload = load
  shadow.appendChild(iframe)
  vmview.close = close
  vmview.mode = mode
  return vmview

  function load () {
    iframe.onload = null
    if (state.closed) return
    const { port1, port2 } = new MessageChannel()
    state.port = port1
    setup_rpc(port1)
    // Opaque sandbox origins require '*'; the port is transferred only to this frame.
    iframe.contentWindow.postMessage({ source: `(${code})(port)`, mode }, '*', [port2])
    done?.(port1, vmview)
  }

  function close () {
    if (state.closed) return
    state.closed = true
    state.port?.postMessage({ type: 'close' })
    state.port?.stop_rpc()
    state.port?.close()
    vmview.remove()
    URL.revokeObjectURL(src)
  }
}

/***************************************
CHILD RUNTIME SOURCE
***************************************/
function get_child_source () {
  return `<!doctype html><html><head><meta charset="utf-8"><link rel="icon" href="data:,"></head><body><script>
setup()
function setup () {
  globalThis.onmessage = connect
  function connect (event) {
    const port = event.ports[0]
    if (!port || !event.data?.source) return
    globalThis.onmessage = null
    ;(${setup_rpc})(port)
    execute(event.data.source, port)
    if (event.data.mode === 'controlled') port.onmessage = run
    function run (message) {
      if (message.data?.type === 'close') return port.close()
      execute(message.data, port)
    }
  }
  function execute (message, port) {
    const source = typeof message === 'string' ? message : message?.source
    if (!source) return
    try { new Function('port', source)(port) } catch (err) {
      port.postMessage({ type: 'vm-error', error: err.message })
    }
  }
}
</script></body></html>`
}

/***************************************
SETUP RPC
***************************************/
function setup_rpc (port) {
  const state = { next_id: 1, pending: new Map(), handlers: new Map(), stopped: false }
  port.request = request
  port.handle = handle
  port.stop_rpc = stop
  port.addEventListener('message', receive)
  port.start()

  function request (name, data) {
    if (state.stopped) return Promise.reject(new Error('Port is closed'))
    const id = state.next_id++
    return new Promise(store)
    function store (resolve, reject) {
      state.pending.set(id, { resolve, reject })
      port.postMessage({ type: 'rpc-request', id, name, data })
    }
  }

  function handle (name, handler) {
    if (handler) state.handlers.set(name, handler)
    else state.handlers.delete(name)
  }

  function receive (event) {
    const message = event.data || {}
    if (message.type !== 'rpc-request' && message.type !== 'rpc-response') return
    event.stopImmediatePropagation()
    if (message.type === 'rpc-request') answer(message)
    else settle(message)
  }

  async function answer (message) {
    const handler = state.handlers.get(message.name)
    if (!handler) return respond({ id: message.id, error: `Unsupported request: ${message.name}` })
    try {
      respond({ id: message.id, data: await handler(message.data) })
    } catch (err) {
      respond({ id: message.id, error: err.message })
    }
  }

  function respond ({ id, data = null, error = null }) {
    port.postMessage({ type: 'rpc-response', id, data, error })
  }

  function settle (message) {
    const pending = state.pending.get(message.id)
    if (!pending) return
    state.pending.delete(message.id)
    if (message.error) pending.reject(new Error(message.error))
    else pending.resolve(message.data)
  }

  function stop () {
    if (state.stopped) return
    state.stopped = true
    port.removeEventListener('message', receive)
    for (const pending of state.pending.values()) pending.reject(new Error('Port is closed'))
    state.pending.clear()
    state.handlers.clear()
  }
}
